}

import { Server as HttpServer } from 'http';
import { Server as SocketServer } from 'socket.io';
import { env } from './env';
import { registerTrackingHandlers, setIo } from '../socket/tracking.gateway';

export function initSocket(httpServer: HttpServer): SocketServer {
  const io = new SocketServer(httpServer, {
    cors: {
      origin: env.FRONTEND_URL,
      credentials: true,
    },
  });

  setIo(io);
  registerTrackingHandlers(io);

  console.log('[Socket.io] Servidor inicializado');
  return io;
}

import { Request, Response } from 'express';
import { AuthService } from '../services/auth.service';
import { prisma } from '../config/database';
import { env } from '../config/env';

const authService = new AuthService(prisma);

const COOKIE_OPTIONS = {
  httpOnly: true,
  secure: env.NODE_ENV === 'production',
  sameSite: 'lax' as const,
  maxAge: 7 * 24 * 60 * 60 * 1000, // 7 días en ms
};

export async function register(req: Request, res: Response): Promise<void> {
  try {
    const { email, password, fullName, career } = req.body;

    // Validaciones básicas
    if (!email || !password || !fullName) {
      res.status(400).json({ 
        error: 'Email, password y fullName son requeridos' 
      });
      return;
    }

    const result = await authService.register(email, password, fullName, career);
    res.status(201).json(result);
  } catch (error: any) {
    console.error('❌ Error en registro:', error.message);

    // Errores conocidos (AppError)
    if (error.statusCode) {
      res.status(error.statusCode).json({ error: error.message });
      return;
    }

    // Error de conexión a BD
    if (error.message.includes('Authentication failed')) {
      res.status(503).json({ 
        error: 'No se puede conectar a la base de datos. Verifica que PostgreSQL esté corriendo.',
        details: error.message 
      });
      return;
    }

    // Otros errores
